mapper.select:
select  from minor_guardian_authorization
where invite_token_hash = #{inviteTokenHash}
for update

mapper.update:
update minor_guardian_authorization
set invite_token_hash = #{inviteTokenHash}, invite_expires_at = #{inviteExpiresAt}, update_time = #{now}
where id = #{id} and guardian_member_id = #{guardianMemberId} and status = 'PENDING'

update minor_guardian_authorization
set status = 'ACTIVE', ward_member_id = #{wardMemberId}, valid_from = #{validFrom}, valid_until = #{validUntil},
    ward_confirmed_at = #{now}, invite_token_hash = null, invite_expires_at = null, update_time = #{now}
where id = #{id} and status = 'PENDING' and invite_token_hash = #{inviteTokenHash}
  and guardian_member_id != #{wardMemberId}

update minor_guardian_authorization
set status = 'SUPERSEDED', update_time = #{now}
where ward_member_id = #{wardMemberId} and guardian_member_id = #{guardianMemberId}
  and purpose = #{purpose} and status = 'ACTIVE' and id != #{exceptId}

mapper.select:
select count(*) from minor_guardian_authorization
where ward_member_id = #{wardMemberId} and purpose = #{purpose} and status = 'ACTIVE'
  and policy_version = #{policyVersion}
  and valid_from <= #{now} and valid_until > #{now}

select count(*) from minor_guardian_authorization
where guardian_member_id = #{guardianMemberId} and ward_member_id = #{wardMemberId} and status = 'ACTIVE'
  and policy_version = #{policyVersion}
  and valid_from <= #{now} and valid_until > #{now}
